package com.hms.notifications;
import com.hms.tenancy.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/notifications") public class NotificationStatusController {private final TenantRepository tenants;private final NotificationMessageRepository messages;public NotificationStatusController(TenantRepository t,NotificationMessageRepository m){tenants=t;messages=m;} @PatchMapping("/{messageId}/status") public NotificationMessage update(@PathVariable String tenantSlug,@PathVariable UUID messageId,@Valid @RequestBody UpdateNotificationStatusRequest r){UUID tenant=tenants.findBySlug(tenantSlug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(tenantSlug));NotificationMessage message=messages.findById(messageId).filter(x->x.getTenantId().equals(tenant)).orElseThrow(()->new IllegalArgumentException("Notification not found"));messages.updateStatus(messageId,tenant,r.status(),r.failureReason());return messages.findById(message.getId()).orElseThrow();}}
